HISTORICAL_SHA = 'dd3ef63993269a16736f7515e3f416e5adc040ec89d6cc5adbb9e13e7c41e6f2'
HISTORICAL_VERSION = 'unique-full-native-semantic-identity-v2'

def require_compatible_policy(digest, queries):
    if not isinstance(queries,(list,tuple)) or not queries or any(q not in POLICIES for q in queries):
        raise ValueError('Explicit known geographical policy names required')
    if digest == POLICY_SHA:return True
    if digest != HISTORICAL_SHA or VERSION != HISTORICAL_VERSION:
        raise ValueError('Unknown or incompatible native identity policy')
    payload={'version':HISTORICAL_VERSION,'policies':HISTORICAL_POLICIES,
      'missing_addresstype_resolution':'explicit_native_address_role_or_place_extratag_same_semantic_name',
      'present_addresstype_resolution':'must_match_declared_role_no_fallback',
      'native_namedetail_aliases':['name','name:en','official_name','short_name','alt_name','_place_name'],
      'no_provider_rank_or_implicit_default':True}
    if fingerprint(payload)!=HISTORICAL_SHA or any(HISTORICAL_POLICIES.get(q)!=POLICIES[q]for q in queries):
        raise ValueError('Selected geographical policy changed; new validation required')
    return True
